import Model from 'flarum/common/Model';
/**
 * One marked passage, client side.
 *
 * 🚨 `note` is not always present: the API serialises it for its author only,
 * so on somebody else's public mark the attribute is simply absent rather than
 * empty. Anything reading it has to treat undefined as "not mine to see".
 */
export default class Highlight extends Model {
  isPublic() {
    return Model.attribute('isPublic').call(this);
  }
  note() {
    return Model.attribute('note').call(this);
  }
  start() {
    return Model.attribute('start').call(this);
  }
  length() {
    return Model.attribute('length').call(this);
  }
  quoted() {
    return Model.attribute('quoted').call(this);
  }
  prefix() {
    return Model.attribute('prefix').call(this);
  }
  suffix() {
    return Model.attribute('suffix').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
  post() {
    return Model.hasOne('post').call(this);
  }
}
flarum.reg.add('ernestdefoe-marginalia', 'forum/models/Highlight', Highlight);